  if (!template?.name || !template?.language) {
    throw new Error('WhatsApp template needs a name and a language code');
  }
  return {
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to,
    type: 'template',
    template: {
      name: template.name,
      language: { code: template.language },
      components: [
